        c = new ReentrancyDAO();
    }

    function _run(uint256 amount, uint256 firstValue) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(firstValue != amount);
        try c.deposit{value: amount}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint balMid = address(c).balance;
        uint thisMid = address(this).balance;
        bool secondReverted;
        try c.withdrawAll() { secondReverted = false; } catch { secondReverted = true; }
        assertTrue(!reverted || (secondReverted || address(c).balance == balMid - amount));
    }

    function testFuzz_run(uint256 amount, uint256 firstValue) public {
        _run(amount, firstValue);
    }

    receive() external payable {}
}
